-- 주간 콘텐츠 2026-10-05 (월): 번역 연습 5문장(이번 주부터 5개) + 주간 리포트 2 + 영어 카피 브리프 3 + 교차번역 2회차 6개
-- 이메일은 저장하지 않고 이름으로 찾아요(members.display_name).
begin;
insert into public.drills (id, dir, topic, sort, context, source, for_author, focus) values
  ('dr-20261005-ke-m1','KR→EN','marketing',1,'북카페 가을 이벤트 포스터','책 한 권을 고르면 커피는 저희가 내려 드려요. 이번 달 마지막 주말까지예요.',(select email from public.members where display_name='희주'),'원문 두 문장을 모두 옮기기'),
  ('dr-20261005-ke-t1','KR→EN','travel',1,'호텔 프런트에 부탁하기','우산 하나 빌릴 수 있을까요? 그리고 내일 아침 6시에 택시 두 대 불러 주세요.',(select email from public.members where display_name='혜림'),'관사 a/an과 숫자 앞 명사'),
  ('dr-20261005-ke-b1','KR→EN','business',1,'거래처에 견적서 다시 요청','지난주에 보내 주신 견적서에 배송비가 빠져 있는 것 같습니다. 확인 후 다시 보내 주시면 감사하겠습니다.',null,''),
  ('dr-20261005-ek-d1','EN→KR','daily',1,'친구가 약속 장소를 정하라고 할 때','Honestly, I''m easy. Pick whatever''s closest to you.',null,''),
  ('dr-20261005-ek-m1','EN→KR','marketing',1,'가습기 제품 상세 페이지 첫 문장','Quiet enough for a nursery. Smart enough to know when to stop.',null,'');
insert into public.drill_models (drill_id, best, alternatives, notes) values
  ('dr-20261005-ke-m1','Pick a book, and the coffee''s on us. Through the last weekend of the month.','["Choose any book and we''ll pour you a coffee. Until the last weekend of this month.", "Buy a book, get a coffee on the house — through the final weekend of the month."]','[{"phrase": "커피는 저희가 내려 드려요 → the coffee''s on us / on the house", "why": "free coffee라고 직접 말하기보다, 가게가 대접한다는 관용 표현이 광고에서 더 자연스러워요."}, {"phrase": "~까지예요 → Through / Until ~", "why": "기한 안내예요. through는 그 주말을 포함한다는 뜻이 분명해요."}, {"phrase": "둘째 문장(기한)", "why": "짧은 카피라도 두 번째 문장을 빠뜨리면 ''언제까지''라는 정보가 사라져요. 끝까지 옮겼는지 확인해요."}]'),
  ('dr-20261005-ke-t1','Could I borrow an umbrella? And could you call two taxis for 6 a.m. tomorrow?','["Is there an umbrella I could borrow? Also, could you book two taxis for six tomorrow morning?", "May I borrow an umbrella? And I''d like two taxis at 6 a.m. tomorrow, please."]','[{"phrase": "우산 하나 → an umbrella", "why": "모음 소리로 시작하는 단어 앞은 an이에요. a/an이 이미 ''하나''라서 one을 또 쓰지 않아요."}, {"phrase": "택시 두 대 → two taxis", "why": "숫자 앞에는 a를 붙이지 않고, 둘 이상이면 명사를 복수형으로 써요."}, {"phrase": "불러 주세요 → call / book", "why": "지금 부르는 건 call, 미리 예약해 두는 건 book이에요. 내일 아침이라 둘 다 자연스러워요."}]'),
  ('dr-20261005-ke-b1','It looks like the shipping cost was left out of the quote you sent last week. Could you check and send it again?','["The quote you sent last week doesn''t seem to include shipping. Would you mind checking and resending it?", "I noticed the quote from last week didn''t include shipping fees. I''d appreciate it if you could take a look and send an updated version."]','[{"phrase": "빠져 있는 것 같습니다 → It looks like ~ was left out", "why": "상대 실수를 단정하지 않는 완곡한 말투예요. It is missing보다 부드러워요."}, {"phrase": "다시 보내 주시면 감사하겠습니다 → Could you ~? / I''d appreciate it if ~", "why": "I will be thankful처럼 직역하지 않아요. 업무 메일의 정해진 부탁 표현이에요."}, {"phrase": "견적서 → quote", "why": "quotation도 맞지만 업무 메일에서는 quote가 가장 흔해요."}]'),
  ('dr-20261005-ek-d1','난 진짜 아무 데나 괜찮아. 너 가까운 데로 골라.','["솔직히 난 상관없어. 너한테 제일 가까운 데로 하자.", "난 다 좋아. 너 편한 데로 정해."]','[{"phrase": "I''m easy → 난 아무 데나 괜찮아", "why": "''나는 쉬워''가 아니에요. 고르는 걸 상대에게 맡길 때 쓰는 구어예요."}, {"phrase": "Honestly → 진짜, 솔직히", "why": "구어에서는 가벼운 강조라 ''정직하게''로 옮기지 않아요."}, {"phrase": "whatever''s closest to you → 너 가까운 데", "why": "''너에게 가장 가까운 무엇이든''처럼 풀어 쓰면 번역투예요. 말하듯 짧게 줄여요."}]'),
  ('dr-20261005-ek-m1','아기 방에 둬도 될 만큼 조용하게. 멈출 때를 알 만큼 똑똑하게.','["아기 방에 둬도 될 만큼 조용하고, 알아서 멈출 만큼 똑똑해요.", "아기가 자는 방에서도 조용히. 습도가 차면 알아서 멈춰요."]','[{"phrase": "Quiet enough for ~ → ~에 둬도 될 만큼 조용한", "why": "''~을 위해 충분히 조용한''은 번역투예요. ''~해도 될 만큼''으로 풀어요."}, {"phrase": "nursery → 아기 방", "why": "여기서는 어린이집(nursery school)이 아니라 아기가 자는 방이에요."}, {"phrase": "Quiet enough / Smart enough", "why": "두 문장이 대구를 이뤄요. 한국어도 ''~하게. ~하게.''처럼 리듬을 맞추면 카피 맛이 살아요."}]');
with s as (
  insert into public.sessions (no, dir, level, title, source) values
    (2,'KR→EN','쉬움','일상 · 택배 부탁','택배가 오면 대신 좀 받아 주실 수 있을까요? 저녁 7시쯤 찾으러 갈게요.'),
    (2,'EN→KR','쉬움','안내문 · 수영장 점검','The pool will be closed for maintenance from October 12 to 14. We apologize for any inconvenience and thank you for your patience.'),
    (2,'KR→EN','보통','생활 기사 · 동네 서점','한 동네 서점이 문을 닫는 대신 ''책 맡기기'' 서비스를 시작했다. 주민이 다 읽은 책을 맡기면 서점이 대신 팔아 주고, 판매 금액의 절반을 돌려준다. 문을 연 지 한 달 만에 맡겨진 책이 800권을 넘었다.'),
    (2,'EN→KR','보통','생활 기사 · 흑백 화면','More people are setting their phones to grayscale in the evening. Users say the dull colors make scrolling less tempting, and some report falling asleep faster. Experts note, however, that the effect varies from person to person.'),
    (2,'KR→EN','실전','대역 기사 · 문화 (예시 원문)','주요 공연장들이 공연 시작 10분 전 남은 좌석을 반값에 파는 ''마지막 10분 티켓''을 도입하고 있다. 빈자리를 줄이고 젊은 관객을 끌어들이려는 시도다. 다만 정가를 내고 일찍 예매한 관객의 반발을 어떻게 달랠지는 과제로 남았다.'),
    (2,'EN→KR','실전','대역 기사 · 경제 (예시 원문)','For the past year, a mid-sized city has paid residents to repair rather than replace household appliances, covering up to 50 percent of the cost. Officials say the program has cut bulky waste by a fifth. Critics counter that the subsidy mostly benefits households that could already afford repairs.')
  returning id, title
)
insert into public.session_models (session_id, best, alternatives, notes)
select s.id, m.best, m.alternatives::jsonb, m.notes::jsonb
from s join (values
  ('일상 · 택배 부탁','Would you mind taking in a package for me if it arrives? I''ll come pick it up around 7 this evening.','["Could you hold on to a delivery for me if it comes today? I''ll swing by around 7 tonight to get it.", "If a package shows up, could you grab it for me? I''ll come by for it around 7 p.m."]','[{"phrase": "대신 받아 주다 → take in a package / hold on to", "why": "receive instead of me로 옮기면 어색해요. 이웃에게 맡길 때는 take in, hold on to를 써요."}, {"phrase": "~해 주실 수 있을까요? → Would you mind ~ing?", "why": "정중한 부탁이에요. mind 뒤에는 동명사(-ing)가 와요."}, {"phrase": "찾으러 갈게요 → I''ll come pick it up", "why": "go to find가 아니에요. 맡긴 물건을 가지러 가는 건 pick up이에요."}]'),
  ('안내문 · 수영장 점검','10월 12일부터 14일까지 시설 점검으로 수영장 운영을 쉽니다. 이용에 불편을 드려 죄송합니다. 양해해 주셔서 감사합니다.','["수영장은 시설 점검으로 10월 12일부터 14일까지 휴장합니다. 이용에 불편을 드려 죄송합니다.", "10월 12~14일에는 정기 점검으로 수영장을 이용하실 수 없습니다. 너그러운 양해 부탁드립니다."]','[{"phrase": "closed for maintenance → 점검으로 휴장합니다", "why": "''유지 보수를 위해 닫힙니다''는 번역투예요. 안내문에서는 휴장, 운영을 쉽니다처럼 현장 말을 써요."}, {"phrase": "We apologize for any inconvenience → 불편을 드려 죄송합니다", "why": "any를 ''어떠한''으로 옮기지 않아요. 한국 안내문에 정해진 문구가 있어요."}, {"phrase": "thank you for your patience → 양해해 주셔서 감사합니다", "why": "''인내에 감사합니다''는 어색해요. 안내문에서는 양해, 협조를 써요."}]'),
  ('생활 기사 · 동네 서점','Rather than close its doors, a neighborhood bookstore has launched a book consignment service. Residents bring in books they''ve finished, the store sells them on their behalf, and the residents get half of each sale. Within the first month, more than 800 books had been dropped off.','["Instead of shutting down, a local bookshop has started taking in residents'' used books on consignment and returning half of every sale to the owner. More than 800 books arrived in the first month alone.", "A neighborhood bookstore has chosen consignment over closure: it sells residents'' finished books for them and splits the proceeds 50-50. Over 800 books came in during the first month."]','[{"phrase": "문을 닫는 대신 → Rather than close its doors", "why": "instead of closing도 맞아요. 기사 첫 문장에서는 rather than이 조금 더 기사체예요."}, {"phrase": "책 맡기기 → consignment", "why": "남의 물건을 맡아 대신 파는 거래는 consignment예요. book keeping이라고 하면 ''장부 정리''로 읽혀요."}, {"phrase": "한 달 만에 ~을 넘었다 → Within the first month, more than ~", "why": "''만에''는 within, in the first month로. ''넘었다''는 숫자 앞 more than으로 옮겨요."}]'),
  ('생활 기사 · 흑백 화면','저녁마다 휴대폰을 흑백 화면으로 바꿔 두는 사람이 늘고 있다. 사용자들은 색이 칙칙해지니 화면을 넘기고 싶은 마음이 덜하다고 말하고, 잠이 더 빨리 든다는 사람도 있다. 다만 전문가들은 효과가 사람마다 다르다고 덧붙인다.','["저녁에 스마트폰을 흑백 모드로 쓰는 사람이 많아졌다. 색이 사라지면 자꾸 들여다보게 되지 않고 잠도 빨리 온다는 후기가 있다. 그러나 전문가들은 사람마다 효과가 다르다고 본다.", "밤이 되면 휴대폰을 흑백으로 바꾸는 사람이 늘었다. 화면이 밋밋해져 손이 덜 간다는 반응이 많고, 일찍 잠든다는 이들도 있다. 다만 효과에는 개인차가 있다는 게 전문가들의 설명이다."]','[{"phrase": "More people are ~ing → ~하는 사람이 늘고 있다", "why": "''더 많은 사람들이 ~하고 있다''는 번역투예요. 기사체에서는 ''늘고 있다''로 옮겨요."}, {"phrase": "less tempting → ~하고 싶은 마음이 덜하다, 손이 덜 간다", "why": "''덜 유혹적이다''는 어색해요. 행동으로 풀어요."}, {"phrase": "Experts note, however, → 다만 전문가들은 ~고 덧붙인다", "why": "문장 가운데 however를 앞으로 빼 ''다만''으로 시작하면 한국어 기사 흐름이 자연스러워요."}]'),
  ('대역 기사 · 문화 (예시 원문)','Major performance venues are rolling out "last-ten-minute tickets," selling unsold seats at half price ten minutes before curtain. The move aims to fill empty seats and draw younger audiences. How to placate patrons who booked early at full price, however, remains an open question.','["Leading concert halls and theaters have begun offering half-price \"last 10 minutes\" tickets for seats still empty shortly before showtime, hoping to cut vacancies and attract younger crowds. Still unresolved is how to handle pushback from early buyers who paid full price.", "A growing number of major venues now sell leftover seats at 50% off ten minutes before a show starts, in a bid to fill empty seats and bring in younger audiences. The challenge is how to appease those who bought full-price tickets in advance."]','[{"phrase": "도입하고 있다 → are rolling out / have begun offering", "why": "introduce도 되지만, 새 제도를 여러 곳이 차례로 시행할 때 기사에서는 roll out을 자주 써요."}, {"phrase": "~하려는 시도다 → The move aims to / in a bid to", "why": "It is an attempt to로 직역하기보다 기사체 관용 표현을 써요."}, {"phrase": "과제로 남았다 → remains an open question / The challenge is", "why": "remain as a task는 어색해요. 풀리지 않은 문제는 open question, challenge로 말해요."}]'),
  ('대역 기사 · 경제 (예시 원문)','한 중소 도시가 지난 1년간 가전제품을 바꾸지 않고 고쳐 쓰는 주민에게 수리비를 최대 50%까지 지원해 왔다. 시 관계자들은 이 사업으로 대형 폐기물이 5분의 1 줄었다고 밝혔다. 반면 비판하는 쪽에서는 지원금이 주로 원래 수리비를 감당할 수 있던 가구에 돌아간다고 반박한다.','["가전제품을 새로 사는 대신 고쳐 쓰면 비용의 절반까지 지원하는 제도를 한 중소 도시가 1년째 운영하고 있다. 시는 대형 폐기물이 20% 줄었다고 설명했다. 그러나 형편이 넉넉한 가구만 혜택을 본다는 비판도 나온다.", "한 중소 도시는 1년 전부터 주민이 가전을 바꾸지 않고 수리하면 비용을 최대 절반까지 대 주고 있다. 당국은 이 덕분에 대형 쓰레기가 5분의 1가량 줄었다고 밝혔지만, 수리할 여력이 이미 있던 가구에 혜택이 쏠린다는 지적도 있다."]','[{"phrase": "paying residents to repair → 고쳐 쓰는 주민에게 수리비를 지원", "why": "''주민에게 돈을 지불한다''로 직역하면 일한 대가를 주는 것처럼 읽혀요. 기사에서는 ''지원''이에요."}, {"phrase": "by a fifth → 5분의 1(20%) 줄었다", "why": "by는 줄어든 폭이에요. ''5분의 1로 줄었다''(80% 감소)와 헷갈리지 않게 옮겨요."}, {"phrase": "Critics counter that → 비판하는 쪽에서는 ~고 반박한다", "why": "counter는 앞 주장에 맞서는 말이라 ''반박한다'', ''지적도 나온다''로 옮겨요."}]')
) as m(title,best,alternatives,notes) on m.title = s.title;
insert into public.weekly_reports (author, week_of, body) values
  ((select email from public.members where display_name='희주'),'2026-10-05','지난 한 주 번역 연습 14문장을 내고 피드백을 1번 요청했어요.
자주 틀린 것 3가지예요.
1. 원문 둘째 문장 빠뜨리기 → The wait is over. Get yours today. 짧은 카피라도 두 문장을 끝까지 옮겨야 정보가 살아요. (2번 나왔어요)
2. date → plans. 친구와의 약속은 plans예요. date는 데이트에 가까워요.
3. Family meeting → a family gathering. meeting은 회의라서 가족 모임은 gathering이에요.
좋아진 점: 9월 28일 이후로 오답 노트에 새로 쌓인 표현이 없어요.
이번 주 번역 연습에 나를 위한 문장 1개를 넣었어요(북카페 포스터, 두 문장 모두 옮기기).
새로 생긴 🔁 다시 도전에서 1주일 전 문장을 하루 3개씩 다시 옮겨 보면, 위 실수가 정말 고쳐졌는지 확인할 수 있어요.'),
  ((select email from public.members where display_name='혜림'),'2026-10-05','지난 한 주 번역 연습 68문장을 내고 피드백을 4번 요청했어요. 정말 많이 했어요.
자주 틀린 것 3가지예요.
1. 관사: a umbrella → an umbrella, a one button → one button, a two fastest ticket → two tickets. 모음 소리 앞은 an, 숫자 앞에는 a를 붙이지 않아요.
2. It''s raining this afternoon → It''s supposed to rain this afternoon. 들은 일기 예보는 be supposed to로 말해요.
3. for fix → to fix. ''~하려고''는 to + 동사원형이에요.
좋아진 점: 9월 29일에 쌓인 오답 4개 중 3개는 단어 선택(serve, until, restock)이었어요. 기본 문법보다 어울리는 표현을 고르는 단계로 넘어가고 있어요.
이번 주 번역 연습에 나를 위한 문장 1개를 넣었어요(호텔 프런트, 관사 a/an과 숫자).
제안해 주신 🔁 다시 도전이 생겼어요. 1주일 전에 낸 문장을 하루 3개씩 다시 옮겨 보세요.')
on conflict (author, week_of) do nothing;
insert into public.copy_briefs (id, week, title, product, target, tone, rules, sort) values
  ('cb-20261005-1','2026-10-05','Fernwick · 화분 물 주기 센서','화분 흙에 꽂아 두면 물이 필요할 때 휴대폰으로 알려 주는 센서. 배터리는 1년 가요. 개당 24달러.','식물을 자꾸 말려 죽이는 바쁜 1인 가구','위트 있게. 식물이 직접 말을 거는 듯한 1인칭으로.','앱 푸시 알림 문구 1줄, 영어 50자 이내. smart, innovative는 쓰지 않아요.',1),
  ('cb-20261005-2','2026-10-05','Nudgepaw · 반려견 동결건조 간식','닭가슴살 하나만 동결건조한 반려견 간식. 첨가물 없음, 한 봉 60g. 작게 부숴서 훈련 간식으로도 써요.','산책과 훈련을 함께 시작한 초보 견주','다정하게. 개와 사람이 함께 보내는 시간을 장면으로.','패키지 앞면 헤드라인 5단어 이하 + 아래 한 줄(12단어 이하). natural, premium은 쓰지 않아요.',2),
  ('cb-20261005-3','2026-10-05','Morrowloaf · 아침 식빵 배달 구독','전날 밤 9시까지 주문하면 다음 날 아침 7시 전에 갓 구운 식빵을 문고리에 걸어 둬요. 주 2회, 한 달 32달러.','아침을 거르고 출근하는 직장인','담백하게. 형용사 대신 아침 장면 하나로.','버스정류장 광고 헤드라인 7단어 이하 + 작은 글씨 1줄. fresh, delicious는 쓰지 않아요.',3)
